
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_o3lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_o3lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.943813868742520e+00, -3.866544478406277e+00, -3.758345075992293e+00, -3.608627330524986e+00, -3.405001125993485e+00, -3.134917297413195e+00, -2.789652017364915e+00, -2.372052994251083e+00, -1.908494495617551e+00, -1.451687128487813e+00, -1.003611033684522e+00, -6.732280383120575e-01, -5.842010192033952e-01, -4.764092593373215e-01, -3.447565265355574e-01, -2.291535558479683e-01, -1.417454313570442e-01, -6.091659954090752e-02, -1.353241491601295e-02, -1.530241320229134e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


